1	#!/usr/bin/env node
2	/**
3	 * SessionStart Hook - Initializes session environment with project detection
4	 *
5	 * Fires: Once per session (startup, resume, clear, compact)
6	 * Purpose: Load config, detect project info, persist to env vars, output context
7	 *
8	 * Exit Codes:
9	 *   0 - Success (non-blocking, allows continuation)
10	 *
11	 * Core detection logic extracted to lib/project-detector.cjs for OpenCode plugin reuse.
12	 */
13	
14	// Crash wrapper
15	try {
16	  const fs = require('fs');
17	  const path = require('path');
18	  const os = require('os');
19	  const {
20	    loadConfig,
21	    writeEnv,
22	    writeSessionState,
23	    resolvePlanPath,
24	    getReportsPath,
25	    resolveNamingPattern,
26	    extractTaskListId,
27	    isHookEnabled
28	  } = require('./lib/ck-config-utils.cjs');
29	
30	  // Early exit if hook disabled in config
31	  if (!isHookEnabled('session-init')) {
32	    process.exit(0);
33	  }
34	
35	  // Import outcome verifier for session-start prediction checks
36	  let getOverduePredictions, formatVerificationPrompt;
37	  try {
38	    ({ getOverduePredictions, formatVerificationPrompt } = require('./lib/outcome-verifier.cjs'));
39	  } catch {
40	    getOverduePredictions = () => [];
41	    formatVerificationPrompt = () => null;
42	  }
43	
44	  // Import shared project detection logic
45	  const {
46	    detectProjectType,
47	    detectPackageManager,
48	    detectFramework,
49	    getPythonVersion,
50	    getGitRemoteUrl,
51	    getGitBranch,
52	    getGitRoot,
53	    getCodingLevelStyleName,
54	    getCodingLevelGuidelines,
55	    buildContextOutput,
56	    execSafe
57	  } = require('./lib/project-detector.cjs');
58	
59	/**
60	 * One-time cleanup for orphaned .shadowed/ directories from skill-dedup hook (Issue #422)
61	 * The hook was disabled due to race conditions; this restores any orphaned skills.
62	 */
63	function cleanupOrphanedShadowedSkills() {
64	  const shadowedDir = path.join(process.cwd(), '.claude', 'skills', '.shadowed');
65	  if (!fs.existsSync(shadowedDir)) return { restored: [], skipped: [], kept: [] };
66	
67	  const skillsDir = path.join(process.cwd(), '.claude', 'skills');
68	  const restored = [];
69	  const skipped = [];
70	  const kept = []; // Skills kept for manual review (content differs)
71	
72	  try {
73	    const entries = fs.readdirSync(shadowedDir, { withFileTypes: true });
74	    for (const entry of entries) {
75	      if (!entry.isDirectory()) continue;
76	      const src = path.join(shadowedDir, entry.name);
77	      const dest = path.join(skillsDir, entry.name);
78	
79	      try {
80	        if (!fs.existsSync(dest)) {
81	          fs.renameSync(src, dest);
82	          restored.push(entry.name);
83	        } else {
84	          // Skill exists in local - verify content match before deleting orphaned copy
85	          const orphanedSkill = path.join(src, 'SKILL.md');
86	          const localSkill = path.join(dest, 'SKILL.md');
87	          if (fs.existsSync(orphanedSkill) && fs.existsSync(localSkill)) {
88	            const orphanedContent = fs.readFileSync(orphanedSkill, 'utf8');
89	            const localContent = fs.readFileSync(localSkill, 'utf8');
90	            if (orphanedContent === localContent) {
91	              // Content identical - safe to remove orphaned duplicate
92	              fs.rmSync(src, { recursive: true, force: true });
93	              skipped.push(entry.name);
94	            } else {
95	              // Content differs - user may have edited orphaned version, keep for review
96	              kept.push(entry.name);
97	            }
98	          } else {
99	            // Missing SKILL.md - safe to remove orphaned copy
100	            fs.rmSync(src, { recursive: true, force: true });
101	            skipped.push(entry.name);
102	          }
103	        }
104	      } catch (err) {
105	        process.stderr.write(`[session-init] Failed to process "${entry.name}": ${err.message}\n`);
106	      }
107	    }
108	    // Clean up manifest and shadowed dir if empty
109	    const manifestFile = path.join(shadowedDir, '.dedup-manifest.json');
110	    if (fs.existsSync(manifestFile)) fs.unlinkSync(manifestFile);
111	    // Only remove shadowed dir if empty (kept skills may remain)
112	    const remaining = fs.readdirSync(shadowedDir);
113	    if (remaining.length === 0) fs.rmdirSync(shadowedDir);
114	    return { restored, skipped, kept };
115	  } catch (err) {
116	    process.stderr.write(`[session-init] Shadowed cleanup error: ${err.message}\n`);
117	    return { restored, skipped, kept };
118	  }
119	}
120	
121	/**
122	 * Detect if this session is running inside an Agent Team.
123	 * Scans ~/.claude/teams/ for active team configs and checks membership.
124	 * Note: Returns first team found — Claude Code supports one team per session.
125	 * Note: Team lifecycle (creation/cleanup) is managed by Claude Code, not this hook.
126	 * @returns {{ teamName: string, memberCount: number } | null}
127	 */
128	function detectAgentTeam() {
129	  try {
130	    const teamsDir = path.join(os.homedir(), '.claude', 'teams');
131	    if (!fs.existsSync(teamsDir)) return null;
132	
133	    const teams = fs.readdirSync(teamsDir, { withFileTypes: true });
134	    for (const entry of teams) {
135	      if (!entry.isDirectory()) continue;
136	      const configPath = path.join(teamsDir, entry.name, 'config.json');
137	      if (!fs.existsSync(configPath)) continue;
138	      try {
139	        const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
140	        if (config.members && config.members.length > 0) {
141	          return { teamName: entry.name, memberCount: config.members.length };
142	        }
143	      } catch { /* skip malformed configs */ }
144	    }
145	    return null;
146	  } catch {
147	    return null;
148	  }
149	}
150	
151	/**
152	 * Main hook execution
153	 */
154	async function main() {
155	  try {
156	    // Issue #422: One-time cleanup of orphaned .shadowed/ from disabled skill-dedup hook
157	    const shadowedCleanup = cleanupOrphanedShadowedSkills();
158	
159	    const stdin = fs.readFileSync(0, 'utf-8').trim();
160	    const data = stdin ? JSON.parse(stdin) : {};
161	    const envFile = process.env.CLAUDE_ENV_FILE;
162	    const source = data.source || 'unknown';
163	    const sessionId = data.session_id || null;
164	
165	    const config = loadConfig();
166	
167	    const detections = {
168	      type: detectProjectType(config.project?.type),
169	      pm: detectPackageManager(config.project?.packageManager),
170	      framework: detectFramework(config.project?.framework)
171	    };
172	
173	    // Resolve plan - now returns { path, resolvedBy }
174	    const resolved = resolvePlanPath(null, config);
175	
176	    // CRITICAL FIX: Only persist explicitly-set plans to session state
177	    // Branch-matched plans are "suggested" - stored separately, not as activePlan
178	    // This prevents stale plan pollution on fresh sessions
179	    if (sessionId) {
180	      writeSessionState(sessionId, {
181	        sessionOrigin: process.cwd(),
182	        // Only session-resolved plans are truly "active"
183	        activePlan: resolved.resolvedBy === 'session' ? resolved.path : null,
184	        // Track suggested plan separately (for UI hints, not for report paths)
185	        suggestedPlan: resolved.resolvedBy === 'branch' ? resolved.path : null,
186	        timestamp: Date.now(),
187	        source
188	      });
189	    }
190	
191	    // Reports path only uses active plans, not suggested ones
192	    const reportsPath = getReportsPath(resolved.path, resolved.resolvedBy, config.plan, config.paths);
193	
194	    // Extract task list ID for Claude Code Tasks coordination (shared helper)
195	    const taskListId = extractTaskListId(resolved);
196	
197	    // Collect static environment info (computed once per session)
198	    const staticEnv = {
199	      nodeVersion: process.version,
200	      pythonVersion: getPythonVersion(),
201	      osPlatform: process.platform,
202	      gitUrl: getGitRemoteUrl(),
203	      gitBranch: getGitBranch(),
204	      gitRoot: getGitRoot(),
205	      user: process.env.USERNAME || process.env.USER || process.env.LOGNAME || os.userInfo().username,
206	      locale: process.env.LANG || '',
207	      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
208	      claudeSettingsDir: path.resolve(__dirname, '..')
209	    };
210	
211	    // Compute base directory for absolute paths (Issue #327: use CWD for subdirectory support)
212	    // Git root is kept in staticEnv for reference, but CWD determines where files are created
213	    const baseDir = process.cwd();
214	
215	    // Compute resolved naming pattern (date + issue resolved, {slug} kept as placeholder)
216	    const namePattern = resolveNamingPattern(config.plan, staticEnv.gitBranch);
217	
218	    if (envFile) {
219	      // Session & plan config
220	      writeEnv(envFile, 'CK_SESSION_ID', sessionId || '');
221	      writeEnv(envFile, 'CK_PLAN_NAMING_FORMAT', config.plan.namingFormat);
222	      writeEnv(envFile, 'CK_PLAN_DATE_FORMAT', config.plan.dateFormat);
223	      writeEnv(envFile, 'CK_PLAN_ISSUE_PREFIX', config.plan.issuePrefix || '');
224	      writeEnv(envFile, 'CK_PLAN_REPORTS_DIR', config.plan.reportsDir);
225	
226	      // NEW: Resolved naming pattern for DRY file naming in agents
227	      // Example: "251212-1830-GH-88-{slug}" or "251212-1830-{slug}"
228	      // Agents use: `{agent-type}-$CK_NAME_PATTERN.md` and substitute {slug}
229	      writeEnv(envFile, 'CK_NAME_PATTERN', namePattern);
230	
231	      // Plan resolution
232	      writeEnv(envFile, 'CK_ACTIVE_PLAN', resolved.resolvedBy === 'session' ? resolved.path : '');
233	      writeEnv(envFile, 'CK_SUGGESTED_PLAN', resolved.resolvedBy === 'branch' ? resolved.path : '');
234	
235	      // Claude Code Tasks integration - enables multi-session/subagent coordination
236	      // Task list ID = plan directory name (shared across all sessions working on same plan)
237	      if (taskListId) {
238	        writeEnv(envFile, 'CLAUDE_CODE_TASK_LIST_ID', taskListId);
239	      }
240	
241	      // Paths - use absolute paths based on CWD for subdirectory workflow support (Issue #327)
242	      writeEnv(envFile, 'CK_GIT_ROOT', staticEnv.gitRoot || '');
243	      writeEnv(envFile, 'CK_REPORTS_PATH', path.join(baseDir, reportsPath));
244	      writeEnv(envFile, 'CK_DOCS_PATH', path.join(baseDir, config.paths.docs));
245	      writeEnv(envFile, 'CK_PLANS_PATH', path.join(baseDir, config.paths.plans));
246	      writeEnv(envFile, 'CK_PROJECT_ROOT', process.cwd());
247	
248	      // Project detection
249	      writeEnv(envFile, 'CK_PROJECT_TYPE', detections.type || '');
250	      writeEnv(envFile, 'CK_PACKAGE_MANAGER', detections.pm || '');
251	      writeEnv(envFile, 'CK_FRAMEWORK', detections.framework || '');
252	
253	      // NEW: Static environment info (so other hooks don't need to recompute)
254	      writeEnv(envFile, 'CK_NODE_VERSION', staticEnv.nodeVersion);
255	      writeEnv(envFile, 'CK_PYTHON_VERSION', staticEnv.pythonVersion || '');
256	      writeEnv(envFile, 'CK_OS_PLATFORM', staticEnv.osPlatform);
257	      writeEnv(envFile, 'CK_GIT_URL', staticEnv.gitUrl || '');
258	      writeEnv(envFile, 'CK_GIT_BRANCH', staticEnv.gitBranch || '');
259	      writeEnv(envFile, 'CK_USER', staticEnv.user);
260	      writeEnv(envFile, 'CK_LOCALE', staticEnv.locale);
261	      writeEnv(envFile, 'CK_TIMEZONE', staticEnv.timezone);
262	      writeEnv(envFile, 'CK_CLAUDE_SETTINGS_DIR', staticEnv.claudeSettingsDir);
263	
264	      // Locale config
265	      if (config.locale?.thinkingLanguage) {
266	        writeEnv(envFile, 'CK_THINKING_LANGUAGE', config.locale.thinkingLanguage);
267	      }
268	      if (config.locale?.responseLanguage) {
269	        writeEnv(envFile, 'CK_RESPONSE_LANGUAGE', config.locale.responseLanguage);
270	      }
271	
272	      // Plan validation config (for /plan validate, /plan --hard, /plan --parallel)
273	      const validation = config.plan?.validation || {};
274	      writeEnv(envFile, 'CK_VALIDATION_MODE', validation.mode || 'prompt');
275	      writeEnv(envFile, 'CK_VALIDATION_MIN_QUESTIONS', validation.minQuestions || 3);
276	      writeEnv(envFile, 'CK_VALIDATION_MAX_QUESTIONS', validation.maxQuestions || 8);
277	      writeEnv(envFile, 'CK_VALIDATION_FOCUS_AREAS', (validation.focusAreas || ['assumptions', 'risks', 'tradeoffs', 'architecture']).join(','));
278	
279	      // Coding level config (for output style selection)
280	      const codingLevel = config.codingLevel ?? 5;
281	      writeEnv(envFile, 'CK_CODING_LEVEL', codingLevel);
282	      writeEnv(envFile, 'CK_CODING_LEVEL_STYLE', getCodingLevelStyleName(codingLevel));
283	
284	    }
285	
286	    // Agent Teams detection — detect once, used for env vars and console output
287	    const teamInfo = detectAgentTeam();
288	    if (envFile && teamInfo) {
289	      writeEnv(envFile, 'CK_AGENT_TEAM', teamInfo.teamName);
290	      writeEnv(envFile, 'CK_AGENT_TEAM_MEMBERS', teamInfo.memberCount);
291	    }
292	
293	    console.log(`Session ${source}. ${buildContextOutput(config, detections, resolved, staticEnv.gitRoot)}`);
294	
295	    // Issue #422: Notify user if orphaned skills were recovered from .shadowed/
296	    const hasCleanup = shadowedCleanup.restored.length > 0 || shadowedCleanup.skipped.length > 0 || shadowedCleanup.kept.length > 0;
297	    if (hasCleanup) {
298	      console.log(`\n[!] SKILL-DEDUP CLEANUP (Issue #422):`);
299	      console.log(`Recovered orphaned .shadowed/ directory from disabled skill-dedup hook.`);
300	      if (shadowedCleanup.restored.length > 0) {
301	        console.log(`Restored ${shadowedCleanup.restored.length} skill(s): ${shadowedCleanup.restored.join(', ')}`);
302	      }
303	      if (shadowedCleanup.skipped.length > 0) {
304	        console.log(`Removed ${shadowedCleanup.skipped.length} duplicate(s): ${shadowedCleanup.skipped.join(', ')}`);
305	      }
306	      if (shadowedCleanup.kept.length > 0) {
307	        console.log(`[!] Kept ${shadowedCleanup.kept.length} skill(s) for manual review (content differs): ${shadowedCleanup.kept.join(', ')}`);
308	        console.log(`    Review .claude/skills/.shadowed/ and merge changes manually.`);
309	      }
310	    }
311	
312	    // Agent Teams: Show team context if running inside a team (uses cached result)
313	    if (teamInfo) {
314	      console.log(`[i] Agent Team detected: "${teamInfo.teamName}" (${teamInfo.memberCount} members)`);
315	      console.log(`    Team config: ~/.claude/teams/${teamInfo.teamName}/config.json`);
316	      console.log(`    Use /team skill for orchestration templates.`);
317	    }
318	
319	    // Info: Show git root when running from subdirectory (Issue #327: now supported)
320	    if (staticEnv.gitRoot && staticEnv.gitRoot !== process.cwd()) {
321	      console.log(`📁 Subdirectory mode: Plans/docs will be created in current directory`);
322	      console.log(`   Git root: ${staticEnv.gitRoot}`);
323	    }
324	
325	    // MITIGATION: Issue #277 - Auto-compact can bypass AskUserQuestion approval gates
326	    // When context is compacted mid-workflow, the summarization may lose "pending approval" state.
327	    // This warning reminds Claude to verify if user approval was pending before proceeding.
328	    // Upstream bug: Claude Code CLI should preserve pending interactive state during compaction.
329	    if (source === 'compact') {
330	      console.log(`\n⚠️ CONTEXT COMPACTED - APPROVAL STATE CHECK:`);
331	      console.log(`If you were waiting for user approval via AskUserQuestion (e.g., Step 4 review gate),`);
332	      console.log(`you MUST re-confirm with the user before proceeding. Do NOT assume approval was given.`);
333	      console.log(`Use AskUserQuestion to verify: "Context was compacted. Please confirm approval to continue."`);
334	    }
335	
336	    // Auto-inject coding level guidelines (if not disabled)
337	    const codingLevel = config.codingLevel ?? -1;
338	    const guidelines = getCodingLevelGuidelines(codingLevel);
339	    if (guidelines) {
340	      console.log(`\n${guidelines}`);
341	    }
342	
343	    if (config.assertions?.length > 0) {
344	      console.log(`\nUser Assertions:`);
345	      config.assertions.forEach((assertion, i) => {
346	        console.log(`  ${i + 1}. ${assertion}`);
347	      });
348	    }
349	
350	    // Outcome verification: surface overdue predictions (max 3)
351	    try {
352	      const overdue = getOverduePredictions(3);
353	      const prompt = formatVerificationPrompt(overdue);
354	      if (prompt) {
355	        console.log(`\n${prompt}`);
356	      }
357	    } catch {}
358	
359	    // AgentMemory sync bridge: quick health check + HITL clear
360	    try {
361	      const cogVenv = path.join(process.cwd(), 'data', 'cognitive', '.venv', 'Scripts', 'python.exe');
362	      const syncScript = path.join(process.cwd(), 'data', 'cognitive', 'scripts', 'agentmemory-sync-bridge.py');
363	      if (fs.existsSync(syncScript)) {
364	        const pythonBin = fs.existsSync(cogVenv) ? cogVenv : 'python';
365	        const { execSync } = require('child_process');
366	        const syncOut = execSync(`"${pythonBin}" "${syncScript}" --quick`, {
367	          timeout: 5000,
368	          encoding: 'utf8',
369	          stdio: ['pipe', 'pipe', 'pipe'],
370	        }).trim();
371	        if (syncOut) console.log(`[AgentMemory] ${syncOut}`);
372	      }
373	    } catch (syncErr) {
374	      // Non-blocking — AgentMemory is optional
375	      if (syncErr.stderr && syncErr.stderr.includes('not running')) {
376	        // Expected when AgentMemory server isn't started — silent
377	      } else {
378	        process.stderr.write(`[session-init] AgentMemory sync skipped: ${syncErr.message}\n`);
379	      }
380	    }
381	
382	    // Memory Tree KB staleness check
383	    try {
384	      const indexPath = path.join(process.cwd(), 'data', 'cognitive', 'INDEX.json');
385	      if (fs.existsSync(indexPath)) {
386	        const index = JSON.parse(fs.readFileSync(indexPath, 'utf8'));
387	        const lastIngest = index.memory_tree?.last_ingest;
388	        if (lastIngest) {
389	          const daysSince = Math.floor((Date.now() - new Date(lastIngest).getTime()) / 86400000);
390	          if (daysSince > 14) {
391	            console.log(`⚠ KB stale: last Memory Tree ingest was ${daysSince} days ago. Run stage0 to refresh.`);
392	          }
393	        }
394	      }
395	    } catch {}
396	
397	    process.exit(0);
398	  } catch (error) {
399	    console.error(`SessionStart hook error: ${error.message}`);
400	    process.exit(0);
401	  }
402	  }
403	
404	  main();
405	} catch (e) {
406	  // Minimal crash logging (zero deps — only Node builtins)
407	  try {
408	    const fs = require('fs');
409	    const p = require('path');
410	    const logDir = p.join(__dirname, '.logs');
411	    if (!fs.existsSync(logDir)) fs.mkdirSync(logDir, { recursive: true });
412	    fs.appendFileSync(p.join(logDir, 'hook-log.jsonl'),
413	      JSON.stringify({ ts: new Date().toISOString(), hook: p.basename(__filename, '.cjs'), status: 'crash', error: e.message }) + '\n');
414	  } catch (_) {}
415	  process.exit(0); // fail-open
416	}
